function pause(){document.body.classList.remove('sim-running');running=false;clearInterval(timer);}
function run(){if(ended)return;running=true;document.body.classList.add('sim-running');clearInterval(timer);timer=setInterval(()=>{const own=getGroups().find(g=>g.id===8);minute=Math.min(own.finishAt,minute+Number($('#speed').value)*.25);update();if(getGroups().find(g=>g.id===8).completed)endRound();},250);update();}
function startRound(){inspectingDelay=false;document.body.classList.remove('inspecting-delay');$('#incident-detail').hidden=true;activeNav('nav-map');setDetailMode('round');document.body.classList.remove('sheet-open');$('#group-scope').value='hole';if(watching){minute=0;choice='auto';$('#scenario').value='auto';lastState='normal';lastAlertAt=-Infinity;$('#traffic-alert').hidden=true;}watching=false;document.body.classList.remove('watching');document.body.classList.add('round-started');started=true;ended=false;selected=8;setFollow(true);selectHole(getGroups().find(g=>g.id===8).hole);addEvent('Your 08:30 tee-time group has started its simulated round.');run();notify('You’re on the course. Tap a group, drag the map, or follow your round.');}
