for(let id=4;id<=11;id++){const element=document.createElement('button');element.className='group-row';const badge=document.createElement('b'),label=document.createElement('span'),name=document.createElement('span'),detail=document.createElement('small'),stage=document.createElement('span');badge.textContent=String(id).padStart(2,'0');name.textContent=id===8?'Your group':'Group '+String(id).padStart(2,'0');label.append(name,detail);element.append(badge,label,stage);element.onclick=()=>{selected=id;setDetailMode('group');setFollow(false);selectHole(getGroups().find(g=>g.id===id).hole);update();openGroupDetails();};rows.set(id,{element,badge,name,detail,stage});$('#group-list').append(element);}
if(L){atlas=L.map('atlas',{minZoom:12,maxZoom:20,zoomSnap:.25,attributionControl:true,preferCanvas:true}).setView([43.187,-124.391],15);atlas.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');atlas.attributionControl.addAttribution('&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a> · ODbL');atlas.on('dragstart',()=>{setFollow(false);document.body.classList.add('map-dragging');});atlas.on('dragend',()=>document.body.classList.remove('map-dragging'));atlas.on('zoomend',()=>{const z=atlas.getZoom();document.body.dataset.zoomDetail=z>=16?'near':'far';if(aerialOn&&z>16.75)setMapDetail(true,{automatic:true});$('#zoom-in').disabled=z>=20;$('#zoom-out').disabled=z<=12;});L.control?.scale?.({imperial:true,metric:false,position:'bottomleft'})?.addTo(atlas);imagery=L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/{z}/{y}/{x}',{minZoom:0,maxZoom:20,maxNativeZoom:16,attribution:'Aerial imagery: USDA / <a href="https://www.usgs.gov/programs/national-geospatial-program/national-map">USGS The National Map</a>'}).on('tileerror',()=>notify('Some aerial imagery could not load. Use Course detail to switch to the local vector map.')).addTo(atlas);}else $('#map-loading').textContent='The map library could not load. Please reload this page.';
