document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$('#atlas').hidden=false;$('#geographic').hidden=true;$('#location').hidden=mode!=='geo';$('#follow').hidden=mode==='geo';$('#start-card').hidden=started||mode!=='atlas';document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#base-layer').hidden=mode!=='atlas';$('#map-caption').textContent=mode==='geo'?'DEVICE GPS STAYS LOCAL · OTHER GROUPS ARE SIMULATED':'USGS AERIAL IMAGERY · OPENSTREETMAP ROUTES · SIMULATED GROUPS';document.body.dataset.mapMode=mode;$('#map-help').querySelector('strong').textContent=mode==='geo'?'Your real location.':'Tap a hole or group.';$('#map-help').querySelector('span').textContent=mode==='geo'?'Enable GPS to see your device alongside simulated groups. Your location stays in this browser.':'Choose a numbered hole to zoom in. Tap a group for details. Drag the map to stop following.';if(mode==='geo'&&!geo&&L){geo=createCourseMap($('#atlas'),{L,map:atlas,onStatus:text=>{if(mode==='geo')$('#map-help').querySelector('span').textContent=text;notify(text);}});geo.setCourse({id:course.id,center:courseData.holes[0].route[0]});}requestAnimationFrame(()=>{if(mode==='geo')geo?.resize();else atlas?.invalidateSize();});});
