$('#change-course').onclick=showLibrary;
const cardPhotos={bandon:'assets/bandon/hole-04.jpg',pinehurst:'assets/pinehurst/flight-01.jpg',pebble:'assets/pebble/flight-07.jpg',sawgrass:'assets/sawgrass/flight-17.jpg'};
function tilePreview(c){const centers={pebble:[36.568,-121.950],sawgrass:[30.198,-81.394]},p=centers[c.id],z=16,n=2**z,x=Math.floor((p[1]+180)/360*n),y=Math.floor((1-Math.asinh(Math.tan(p[0]*Math.PI/180))/Math.PI)/2*n);return `https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/${z}/${y}/${x}`;}
const cardNodes=[];for(const c of courses){const card=document.createElement('button');card.className='course-card';card.dataset.course=c.id;const img=document.createElement('img');img.src=cardPhotos[c.id]||tilePreview(c);img.alt=c.name+' course preview';img.loading='lazy';const text=document.createElement('div'),region=document.createElement('span'),name=document.createElement('h2'),meta=document.createElement('p'),arrow=document.createElement('b');region.textContent=c.region;name.textContent=c.name;meta.textContent='18 holes · interactive traffic demo';arrow.textContent='Watch course traffic ↗';text.append(region,name,meta,arrow);card.append(img,text);card.onclick=()=>{if(intent==='preview'){location.href='preview.html?course='+c.id;return;}switchCourse(c.id);};$('#course-cards').append(card);cardNodes.push({card,course:c});}
$('#library-search').oninput=e=>{const query=e.target.value.trim().toLowerCase();let count=0;for(const {card,course:c} of cardNodes){card.hidden=!(c.name+' '+c.region).toLowerCase().includes(query);if(!card.hidden)count++;}$('#no-course-results').hidden=count>0;};

function watchCourse(){activeNav('nav-map');$('#group-scope').value='course';watching=true;document.body.classList.add('round-started','watching');started=true;ended=false;setFollow(false);addEvent('Watching course traffic. No round joined and no location permission requested.');run();}
function trafficAlert(brief){alertIncident=brief.incident?{...brief.incident,at:minute}:null;$('#inspect-alert').hidden=!alertIncident;const canNotify=minute-lastAlertAt>=3;lastAlertAt=minute;$('#alert-title').textContent=brief.title;$('#alert-body').textContent=brief.message+' '+brief.action;$('#traffic-alert').dataset.kind=brief.state;$('#traffic-alert').hidden=false;$('#nav-traffic').classList.add('has-alert');if(canNotify&&!watching&&!$('#quiet-alerts').checked&&'Notification'in window&&window.Notification.permission==='granted')new window.Notification('Fairway Flow · demo traffic',{body:brief.message,tag:'fairway-demo-traffic'});}
$('#watch').onclick=watchCourse;$('#join-watching').onclick=requestJoin;$('#dismiss-alert').onclick=()=>{$('#traffic-alert').hidden=true;$('#nav-traffic').classList.remove('has-alert');};
$('#enable-alerts').onclick=async()=>{if(!('Notification'in window)){notify('This browser does not support device alerts. In-app alerts will still work.');return;}try{const result=await window.Notification.requestPermission();$('#enable-alerts').textContent=result==='granted'?'Device alerts enabled':'Device alerts not enabled';}catch{notify('Device alerts could not be enabled. In-app alerts remain available.');}};
document.querySelectorAll('[data-intent]').forEach(b=>b.onclick=()=>{intent=b.dataset.intent;document.querySelectorAll('[data-intent]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));for(const {card} of cardNodes)card.querySelector('b').textContent={watch:'Watch course traffic ↗',play:'Select course & start ↗',preview:'Open course preview ↗'}[intent];});
function activeNav(id){document.querySelectorAll('.phone-nav button').forEach(b=>{b.classList.toggle('active',b.id===id);if(b.id===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
$('#nav-home').onclick=()=>{activeNav('nav-home');showLibrary();};$('#nav-map').onclick=()=>{activeNav('nav-map');if(!courseData){showLibrary();return;}$('#course-library').hidden=true;$('#course-workspace').hidden=false;document.body.classList.add('course-selected');document.body.classList.remove('sheet-open');requestAnimationFrame(()=>atlas?.invalidateSize());};$('#nav-traffic').onclick=()=>{setDetailMode('round');$('#nav-traffic').classList.remove('has-alert');if(!courseData){showLibrary();return;}$('#nav-map').onclick();document.body.classList.add('sheet-open');activeNav('nav-traffic');$('#round-panel').scrollIntoView?.({behavior:'smooth',block:'start'});};

$('#group-scope').onchange=updateDetails;

function openGroupDetails(){if(matchMedia('(max-width: 760px)').matches){document.body.classList.add('sheet-open');$('#sheet-toggle').setAttribute('aria-expanded','true');$('#sheet-toggle').textContent=detailMode==='group'?'Close group details ↓':'Close round details ↓';requestAnimationFrame(()=>$('#round-panel').scrollTo?.({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));}}

$('#glance-join').onclick=requestJoin;$('#glance-details').onclick=()=>{setDetailMode('round');openGroupDetails();};$('#back-to-round').onclick=()=>{inspectingDelay=false;document.body.classList.remove('inspecting-delay');$('#incident-detail').hidden=true;setDetailMode('round');selected=8;update();};$('#nav-profile').onclick=()=>showDialog('profile-dialog');
$('#join-form').onsubmit=e=>{e.preventDefault();if($('#join-code').value.trim().toUpperCase()!=='FLOW0830'){$('#join-error').hidden=false;return;}closeDialog('join-dialog');startRound();};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));
$('#hole-menu').onclick=()=>{const open=document.body.classList.toggle('hole-menu-open');$('#hole-menu').setAttribute('aria-expanded',String(open));};
try{$('#quiet-alerts').checked=localStorage.getItem('ff-quiet')==='true';}catch{}
$('#quiet-alerts').onchange=e=>{try{localStorage.setItem('ff-quiet',String(e.target.checked));}catch{}};

function renderTargetInputs(){$('#target-inputs').replaceChildren(...targets.map((n,i)=>{const label=document.createElement('label');label.textContent='H'+(i+1);const input=document.createElement('input');input.type='number';input.min=5;input.max=30;input.step=1;input.value=n;input.required=true;input.setAttribute('aria-label','Hole '+(i+1)+' target minutes');label.append(input);return label;}));}
function renderTrafficContext(groups=getGroups()){if(!courseData)return;const incident=delayIncident(minute,choice,targets);lines.get(5)?.setStyle({color:incident.active?'#efaa55':hole===5?'#f1d189':'#faf4d4',weight:incident.active?5:hole===5?4:1.5,opacity:incident.active?.95:hole===5?.95:.28});const onHole=groups.filter(g=>!g.completed&&g.hole===hole&&minute>=(g.id-8)*10);$('#hole-context-title').textContent='Hole '+hole+' · '+targets[hole-1]+' min target';$('#hole-context-body').textContent=onHole.length+' demo group'+(onHole.length===1?'':'s')+' here. '+(incident.active&&hole===5?'08:20 group is over target. Inspect the delay for the scripted explanation.':'Tap a group to see its playing order and approximate distance.');$('#inspect-hole-delay').hidden=!(incident.active&&hole===5);const gridKey=JSON.stringify([targets,incident.active,groups.map(g=>[g.id,g.hole,minute>=(g.id-8)*10])]);if(!$('#course-traffic').hidden&&gridKey!==courseGridKey){courseGridKey=gridKey;$('#course-hole-grid').replaceChildren(...Array.from({length:18},(_,i)=>{const h=i+1,b=document.createElement('button'),count=groups.filter(g=>!g.completed&&g.hole===h&&minute>=(g.id-8)*10).length;b.textContent='H'+h+' · '+count+' groups · '+targets[i]+' min';b.dataset.delay=String(incident.active&&h===5);b.onclick=()=>{setFollow(false);$('#course-traffic').hidden=true;selectHole(h);if(incident.active&&h===5)inspectDelay(incident);};return b;}));}if(inspectingDelay){const shown=incident.active?incident:alertIncident;if(shown){$('#incident-evidence').textContent=(incident.active?'Active demo delay. ':'Delay cleared in this demo. Earlier observation: ')+Math.floor(shown.elapsed)+' min on hole · '+shown.target+' min target · '+Math.floor(shown.over)+' min over. '+shown.evidence;}}const own=groups.find(g=>g.id===8),sel=groups.find(g=>g.id===selected);if(own&&sel&&own.id!==sel.id){const difference=own.id-sel.id;$('#selected-distance').textContent=Math.abs(difference)+' group'+(Math.abs(difference)===1?'':'s')+' '+(difference>0?'ahead':'behind')+' · hole '+sel.hole;if(!watching&&own.hole===sel.hole&&!own.stale&&!sel.stale){const a=routePosition(ensureHole(own.hole).route,own.fraction),b=routePosition(ensureHole(sel.hole).route,sel.fraction);$('#selected-distance').textContent+=' · approx. '+distanceYards(a,b)+' yd from your group (straight-line demo distance; not a safe-to-hit signal)';if(detailMode==='group'){if(!distanceLine&&L)distanceLine=L.polyline([a,b],{color:'#fff6cc',weight:2,dashArray:'5 8',interactive:false}).addTo(atlas);else distanceLine?.setLatLngs?.([a,b]);}else{distanceLine?.remove();distanceLine=null;}}else{distanceLine?.remove();distanceLine=null;$('#selected-distance').textContent+=watching?' · Join a round for same-hole yardages.':own.stale||sel.stale?' · Yardage unavailable: location uncertain.':' · On a different hole; yardage omitted.';}}else{$('#selected-distance').textContent=watching?'Reference tee-time group · 08:30':'Your tee-time group · 08:30';distanceLine?.remove();distanceLine=null;}}

function inspectDelay(incident=delayIncident(minute,choice,targets)){if(!incident.active&&!alertIncident)return;const shown=incident.active?incident:alertIncident;inspectingDelay=true;document.body.classList.add('inspecting-delay');setFollow(false);setDetailMode('round');$('#course-traffic').hidden=true;$('#incident-detail').hidden=false;$('#incident-evidence').textContent=(incident.active?'Active demo delay. ':'Earlier demo alert. ')+Math.floor(shown.elapsed)+' min on hole · '+shown.target+' min target · '+Math.floor(shown.over)+' min over. '+shown.evidence;$('#incident-reason').textContent=shown.reason;document.querySelector('[data-mode="atlas"]').onclick();selectHole(5);openGroupDetails();requestAnimationFrame(()=>$('#incident-detail').scrollIntoView?.({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'}));}
$('#inspect-alert').onclick=()=>inspectDelay();$('#inspect-hole-delay').onclick=()=>inspectDelay();$('#incident-back').onclick=()=>{$('#incident-detail').hidden=true;inspectingDelay=false;document.body.classList.remove('inspecting-delay');$('#follow').onclick();};$('#close-course-traffic').onclick=()=>$('#course-traffic').hidden=true;
$('#show-delay').onclick=()=>{choice=delayWindow(targets).alertAt<0?'queue':'auto';$('#scenario').value=choice;minute=Math.max(0,delayWindow(targets).alertAt+1);lastAlertAt=-Infinity;lastState='normal';if(!started)watchCourse();update();$('#controls').hidden=true;inspectDelay(delayIncident(minute,choice,targets));};
$('#target-form').onsubmit=e=>{e.preventDefault();try{const next=[...document.querySelectorAll('#target-inputs input')].map(i=>Number(i.value));const persisted=saveTargets(course.id,next);targets=next;$('#reset').onclick();renderTargetInputs();$('#target-status').textContent=persisted?'Saved for this course in this browser. Demo restarted.':'Applied for this session. Browser storage is unavailable.';}catch(error){$('#target-status').textContent=error.message;}};
$('#target-defaults').onclick=()=>{targets=holeTargets(courseData.holes,course.target);try{localStorage.removeItem('ff-targets-'+course.id);}catch{}$('#reset').onclick();renderTargetInputs();$('#target-status').textContent='Illustrative defaults restored. Demo restarted.';};

$('#show-queue').onclick=()=>{$('#show-delay').onclick();minute=delayWindow(targets).clearAt-2;lastAlertAt=-Infinity;update();inspectDelay(delayIncident(minute,choice,targets));};
